// lexicon.js: word lookups for the name tier, backed by public vocabularies.
//
// Pure: no I/O. The data module (./lexicon-data.js) is generated by
// scripts/build-lexicon.mjs from public-domain sources listed in
// data/lexicon/manifest.json. It is decoded once, on first use.
//
// Classes a capitalized word can fall into:
//   clinical    in the drug or diagnosis vocabulary and not in a name list
//   eponymous   in the drug or diagnosis vocabulary and also in a name list,
//               and not an ordinary English word (Parkinson, Crohn, Brian):
//               the context decides
//   nameStrong  in a name list and not an ordinary English word (Inez, Okafor)
//   nameWeak    in a name list and also an ordinary English word (Grace, Price,
//               Bell, Burns), whether or not it is also clinical
//   english     an ordinary English word, or a nationality or language word
//               (Chinese, Hispanic), and not in a name list
//   unknown     in none of the lists

import { foldKey, frontDecode } from "./text-fold.js";
import { PROGRAM_WORDS } from "./grammar.js";
import { SURNAMES, COMMONSURNAMES, FIRST, DRUGS, ICD, ENGLISH, DEMONYMS } from "./lexicon-data.js";

let sets = null;

function load() {
  if (!sets) {
    sets = {
      surnames: frontDecode(SURNAMES),
      commonSurnames: frontDecode(COMMONSURNAMES),
      first: frontDecode(FIRST),
      drugs: frontDecode(DRUGS),
      icd: frontDecode(ICD),
      english: frontDecode(ENGLISH),
      demonyms: frontDecode(DEMONYMS),
    };
  }
  return sets;
}

/** Simple English inflection stems: plural, past tense, gerund, doubled consonants. */
function stems(k) {
  const out = [k];
  if (k.length > 3 && k.endsWith("ies")) out.push(k.slice(0, -3) + "y");
  if (k.length > 3 && k.endsWith("es")) out.push(k.slice(0, -2));
  if (k.length > 2 && k.endsWith("s") && !k.endsWith("ss")) out.push(k.slice(0, -1));
  if (k.length > 4 && k.endsWith("ied")) out.push(k.slice(0, -3) + "y");
  if (k.length > 4 && k.endsWith("ed")) {
    out.push(k.slice(0, -2), k.slice(0, -1));
    if (k.length > 5 && k[k.length - 3] === k[k.length - 4]) out.push(k.slice(0, -3)); // referred, stopped
  }
  if (k.length > 5 && k.endsWith("ing")) {
    out.push(k.slice(0, -3), k.slice(0, -3) + "e");
    if (k.length > 6 && k[k.length - 4] === k[k.length - 5]) out.push(k.slice(0, -4)); // stopping
  }
  return out;
}

function hasAny(set, keys) {
  for (const k of keys) if (set.has(k)) return true;
  return false;
}

const cache = new Map();
// No entry in any list is longer than this. Longer keys skip the lookups, so a
// single huge token costs linear time, not a slice for every split point.
const MAX_KEY = 40;

/**
 * Lookup flags for one word (any case, any diacritics).
 * @returns {{key:string, english:boolean, first:boolean, surname:boolean, commonSurname:boolean, drug:boolean, icd:boolean, demonym:boolean}}
 */
export function lookup(word) {
  const key = foldKey(word);
  const hit = cache.get(key);
  if (hit) return hit;
  if (key.length > MAX_KEY) return { key, english: false, first: false, surname: false, commonSurname: false, drug: false, icd: false, demonym: false };
  const s = load();
  const forms = stems(key);
  const flags = {
    key,
    english: hasAny(s.english, forms),
    first: s.first.has(key),
    surname: s.surnames.has(key),
    commonSurname: s.commonSurnames.has(key),
    drug: hasAny(s.drugs, forms),
    icd: hasAny(s.icd, forms),
    demonym: s.demonyms.has(key),
  };
  if (cache.size > 50000) cache.clear();
  cache.set(key, flags);
  return flags;
}

/** True when an unknown word is two ordinary English words of four or more letters ("callback"). */
function englishCompound(key) {
  const s = load();
  for (let i = 4; i <= key.length - 4; i++) {
    if (s.english.has(key.slice(0, i)) && hasAny(s.english, stems(key.slice(i)))) return true;
  }
  return false;
}

/** Word class used by the name tier (see the header comment). */
export function wordClass(word) {
  const f = lookup(word);
  if (!f.key) return "unknown";
  if (PROGRAM_WORDS.has(f.key)) return "english";
  const name = f.first || f.surname;
  const clinical = f.drug || f.icd;
  if (clinical && !name) return "clinical";
  if (clinical && name && !f.english) return "eponymous";
  if (name && !f.english) return "nameStrong";
  if (name && f.english) return "nameWeak";
  if (f.english || f.demonym) return "english";
  if (f.key.length >= 8 && f.key.length <= MAX_KEY && englishCompound(f.key)) return "english";
  return "unknown";
}

/** True when the word is in the drug or diagnosis vocabulary. */
export function isClinical(word) {
  const f = lookup(word);
  return f.drug || f.icd;
}

/** True when the word is an ordinary English word. */
export function isEnglish(word) {
  return lookup(word).english;
}

export default { lookup, wordClass, isClinical, isEnglish };
